theme.css:
svg .igc-pie-center-text .igc-pie-center-text-node {
	font-family: Roboto Medium, sans-serif;
	font-weight: 400;
	fill: #464646;
	font-size: 19px;
}
.igc-sheet {
	margin-bottom: 15px;
}
.igc-sheets {
	margin-bottom: 15px;
}
.igc-sheets .igc-sheet .igc-sheet-label,
    .igc-sheets .igc-sheet:hover .igc-sheet-label,
        .igc-sheets .igc-sheet.active .igc-sheet-label {
	color: rgba(70, 70, 70, 1);
	margin-left: 5px;
	font: 400 13px Roboto Medium, sans-serif;
}
.igc-sheets .igc-sheet:hover .igc-sheet-label,.igc-sheets .igc-sheet.active .igc-sheet-label {
	color: rgba(70, 70, 70, 0.7);
}
.igc-sheets .igc-sheet .igc-sheet-ico,
    .igc-sheets .igc-sheet:hover .igc-sheet-ico {
	background: rgba(167, 167, 167, 0.3);
	border-color: #464646;
	transition: .2s;
}
.igc-sheets .igc-sheet:hover .igc-sheet-ico {
	background: rgba(167, 167, 167, 1);
}
.igc-sheets .igc-sheet.active .igc-sheet-ico {
	background: #464646;
}
.igc-sheets .igc-sheet.active .igc-sheet-ico::after,
    .igc-sheets .igc-sheet:hover .igc-sheet-ico::after {
	height: 6px;
	width: 6px;
	left: 6px;
	top: 6px;
	background: #fff;
}
.igc-textual-figure {
	font: 400 29px Roboto Medium, sans-serif;
}
.igc-textual-fact {
	color: #464646;
	line-height: 18px;
	font: 400 15px Roboto Medium, sans-serif;
}
.igc-textual-figure .innertext {
	line-height: 30px;
}
.igc-textual-fact .innertext {
	line-height: 19px;
}
.igc-textual-icon {
	padding-right: 30px;
	padding-top: 7px;
}
.igc-table .igc-table-cell {
	font: 400 13px Roboto Medium, sans-serif;
}
.igc-table .igc-table-header {
	font: 400 13px Roboto Medium, sans-serif;
	padding-left: 9px;
}
.ig-container {
	background: #fff;
}
.headline {
	font-weight: 400;
	font-size: 39px;
	font-family: Roboto;
	color: #464646;
	text-align: left;
	line-height: 40px;
	border-bottom: 5px solid #e8e8e8;
	padding-bottom: 10px;
}
.chart-title {
	font: 400 29px Roboto, sans-serif;
	color: #464646;
	text-align: left;
	line-height: 35px;
}
.bodytext {
	font: 400 normal 15px Roboto Medium, sans-serif;
	text-align: left;
	text-align: justify;
	color: #464646;
	line-height: 25px;
}
.quote {
	font: 400 29px Roboto, sans-serif;
	color: #464646;
	line-height: 35px;
	text-align: left;
	background: url(/i/templates/215/quote.svg) left top no-repeat;
	background-size: 50px;
	padding-left: 80px;
	min-height: 40px;
}
.shrink .quote {
	padding-top: 50px;
	padding-left: 0;
}
.quotetitle {
	font: 400 italic 15px Roboto Medium, sans-serif;
	color: #464646;
	margin-top: 5px;
	line-height: 25px;
}
.tt_tooltip {
	color: #fff;
	font: 400 normal 13px Roboto Medium, sans-serif;
}
.igc-legend-entry {
	margin-top: 15px;
}
.igc-legend {
	padding-top: 10px;
	padding-bottom: 0;
}
.footer-bottom {
	padding-top: 15px;
	overflow: hidden;
	padding-bottom: 15px;
}
.ig-logo {
	margin-top: 0px;
}
.ig-separator-line {
	background: rgba(70, 70, 70, 0.5);
}
.heatmap-legend {
	background: rgba(255, 255, 255, 0.7);
}
.heatmap-legend-item,
.heatmap-label {
	color: #464646;
	font-size: 13px;
	font-weight: 400;
	font-family: Roboto, sans-serif;
}
.igc-graph-pie-piece {
	stroke: rgb(255, 255, 255);
}
.tt_tooltip .tt_value {
	font-weight: 400;
}
.tt_tooltip .tt_body {
	background: #333;
}
.tt_tooltip .tt_left {
	border-right: 8px solid #333;
}
.tt_tooltip .tt_right {
	border-left: 8px solid #333;
}
.igc-tabs .igc-tab-active {
	background: #fff;
}
.igc-tabs .igc-tab .igc-tab-content,
          .igc-tabs .igc-tab.icon-down:after {
	font-family: Roboto Medium, sans-serif;
	color: #464646;
	font-weight: 400;
}
.igc-tabs .igc-tab,
          .igc-tab-switcher {
	color: #464646;
}
.igc-tabs.igc-tabs-dropdown .igc-tab-name {
	font-family: Roboto, sans-serif;
	color: #464646;
}
.captiontext {
	font-family: Roboto Medium, sans-serif;
	color: #464646;
	font-weight: 400;
}
.captiontext .innertext {
	line-height: 1.5;
}
.igc-table-search {
	color: #666;
	font-size: 13px;
	font-weight: 400;
	font-family: Roboto Medium, sans-serif;
}
